INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Art. 21(2)(h) ↔ Art. 32(1)(a): encryption at rest and in transit is the same control under both regimes. NIS2 applies it to network and information systems, Art. 32 to personal data, so the measure carries over while the scope statement does not.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = '9.2' AND rb."code" = 'G-TOM.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Art. 21(2)(c) ↔ Art. 32(1)(c): ''the ability to restore the availability and access to personal data in a timely manner in the event of a physical or technical incident'' is what a tested backup and restore programme evidences. A restore that has never been tested evidences neither.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = '4.4' AND rb."code" = 'G-TOM.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Art. 21(2)(c) ↔ Art. 32(1)(c): the disaster recovery plan carries the recovery-time side of the same restore duty. Art. 32(1)(c) bounds it by ''in a timely manner'' rather than by a stated RTO, so the NIS2 target is evidence for it and not a substitute.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = '4.3' AND rb."code" = 'G-TOM.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Art. 21(2)(f) ↔ Art. 32(1)(d): ''a process for regularly testing, assessing and evaluating the effectiveness of technical and organisational measures''. The CIR 7.1 KPI records are that process running. Art. 32(1)(d) is the one enumerated item creating an ongoing duty rather than a one-off measure.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = '7.1' AND rb."code" = 'G-TOM.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Art. 21(2)(f) ↔ Art. 32(1)(d): the internal audit programme is the assessing and evaluating half of the same clause, where 7.1 is the measuring half.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = '7.2' AND rb."code" = 'G-TOM.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Art. 21(2)(i) ↔ Art. 32(1)(b): the access control policy is the primary evidence for ''ongoing confidentiality'' of processing systems. Art. 32(1)(b) also covers integrity, availability and resilience, which this requirement does not reach.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = '10.1' AND rb."code" = 'G-TOM.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Art. 21(2)(j) ↔ Art. 32 by implication: Art. 32 nowhere names MFA, and its ''appropriate measures'' clause is what carries it. CIR 11.7 mandates MFA outright for the eleven digital-service entity types; for everyone else Art. 21(1) proportionality decides, exactly as Art. 32(1) does. Never ''equivalent'': one is a named control, the other an open standard that the control happens to meet.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = '11.1' AND rb."code" = 'G-TOM.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Art. 23(1) subpara. 2 ↔ Art. 34: both require telling people outside the authority about an incident, and the post-incident communication is where a company decides who hears what. The duties do not merge. NIS2 addresses the recipients of the service when provision is adversely affected; Art. 34 addresses the data subjects when the breach is likely to result in a high risk to their rights and freedoms, and the Art. 34(3) carve-outs apply to the GDPR side only.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = '3.5' AND rb."code" = 'G-BRC.3' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'Fundamental Rights Impact Assessment overlaps with the GDPR Art. 35 DPIA when the AI system processes personal data.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = 'AI-FRI.1' AND rb."code" = 'G-TOM.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
--> statement-breakpoint
