INSERT INTO "requirement_satisfaction" ("requirement_a_id", "requirement_b_id", "rationale", "equivalence_kind") SELECT ra."id", rb."id", 'AI Act Art. 73 incident response procedure overlaps with the GDPR Art. 33 breach response procedure when the incident involves personal data.', 'overlapping'::"equivalence_kind" FROM "requirement" ra, "requirement" rb WHERE ra."code" = 'AI-INC.1' AND rb."code" = 'G-BRC.1' ON CONFLICT ON CONSTRAINT "uq_satisfaction_pair" DO UPDATE SET "rationale" = EXCLUDED."rationale", "equivalence_kind" = EXCLUDED."equivalence_kind";
